def list_laravel_docs(version=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # No explicit auth parameters in this API; ambiently authorized.

    # Validate inputs
    if version is not None and not isinstance(version, str):
        return _err("VALIDATION_ERROR", "version must be a string or null")
    if isinstance(version, str):
        v = version.strip()
        if v == "":
            return _err("VALIDATION_ERROR", "version must not be empty")
        # Framework version keys are typically like "11.x", "10.x", etc.
        if not re.fullmatch(r"\d+\.(x|\d+)", v):
            return _err("VALIDATION_ERROR", "invalid version format; expected like '11.x' or '11.0'", version=version)
        version = v

    sources = _load("doc_sources.json")
    files = _load("doc_files.json")

    # Resolve framework sources
    framework_sources = [s for s in sources if isinstance(s, dict) and s.get("source_type") == "framework" and s.get("status") == "active"]
    if version is not None:
        framework_sources = [s for s in framework_sources if s.get("key") == version]
        if not framework_sources:
            return _err("NOT_FOUND", "requested framework version not present in cache", version=version)

    framework_source_ids = {s.get("id") for s in framework_sources if s.get("id")}
    # Business rule: list_laravel_docs returns active doc_files for framework sources
    matched = []
    for f in files:
        if not isinstance(f, dict):
            continue
        if f.get("status") != "active":
            continue
        if f.get("source_id") in framework_source_ids:
            matched.append(f)

    # Sort for stable discovery: by source key then filename
    source_key_by_id = {s.get("id"): s.get("key") for s in framework_sources}
    def _sort_key(row):
        return (str(source_key_by_id.get(row.get("source_id"), "")), str(row.get("filename", "")))
    matched.sort(key=_sort_key)

    # Return unpaged list of filenames/paths (include version for clarity)
    results = []
    for f in matched:
        sid = f.get("source_id")
        results.append({
            "version": source_key_by_id.get(sid),
            "filename": f.get("filename"),
            "title": f.get("title"),
            "category": f.get("category"),
            "word_count": f.get("word_count"),
        })

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": results,
        "meta": {
            "version": version,
            "count": len(results),
            "execution_ms": latency_ms,
        }
    }

def search_laravel_docs(query, version=None, include_external=True, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _ulid():
        # Deterministic-enough ULID-like (26 chars Crockford base32) using timestamp+random
        import os as _os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        # 48-bit timestamp + 80-bit randomness
        ts = ms & ((1 << 48) - 1)
        rnd = int.from_bytes(_os.urandom(10), "big")
        val = (ts << 80) | rnd
        out = []
        for _ in range(26):
            out.append(alphabet[val & 31])
            val >>= 5
        return "".join(reversed(out))

    t0 = time.time()

    # Validate inputs
    if not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    q = query.strip()
    if len(q) < 1 or len(q) > 2048:
        return _err("VALIDATION_ERROR", "query length must be between 1 and 2048 characters")
    if version is not None and not isinstance(version, str):
        return _err("VALIDATION_ERROR", "version must be a string or null")
    if version is not None:
        v = version.strip()
        if v == "":
            return _err("VALIDATION_ERROR", "version must not be empty")
        if not re.fullmatch(r"\d+\.(x|\d+)", v):
            return _err("VALIDATION_ERROR", "invalid version format; expected like '11.x' or '11.0'", version=version)
        version = v
    if not isinstance(include_external, bool):
        return _err("VALIDATION_ERROR", "include_external must be boolean")

    sources = _load("doc_sources.json")
    files = _load("doc_files.json")
    search_log = _load("search_queries.json")

    # Resolve scope
    framework_sources_all_active = [s for s in sources if isinstance(s, dict) and s.get("source_type") == "framework" and s.get("status") == "active"]
    if version is not None:
        framework_sources = [s for s in framework_sources_all_active if s.get("key") == version]
        if not framework_sources:
            return _err("NOT_FOUND", "requested framework version not present in cache", version=version)
        framework_source_id = framework_sources[0].get("id")
        framework_source_ids = {framework_source_id} if framework_source_id else set()
    else:
        framework_source_id = None
        framework_source_ids = {s.get("id") for s in framework_sources_all_active if s.get("id")}

    service_sources_active = []
    if include_external:
        service_sources_active = [s for s in sources if isinstance(s, dict) and s.get("source_type") == "service" and s.get("status") == "active"]
    service_source_ids = {s.get("id") for s in service_sources_active if s.get("id")} if include_external else set()

    # If no sources at all, treat as NOT_FOUND for selected scope
    if not framework_source_ids and not service_source_ids:
        return _err("NOT_FOUND", "no active documentation sources available for the selected scope")

    # Tokenize query
    tokens = [t for t in re.split(r"\s+", q.lower()) if t]
    # Simple full-text matching against content_markdown; compute per-document hit counts (sum of occurrences)
    def _count_hits(text):
        if not text:
            return 0
        lt = text.lower()
        total = 0
        for tok in tokens:
            if tok:
                total += lt.count(tok)
        return total

    results = []
    for f in files:
        if not isinstance(f, dict):
            continue
        if f.get("status") != "active":
            continue
        sid = f.get("source_id")
        if sid in framework_source_ids or sid in service_source_ids:
            hits = _count_hits(f.get("content_markdown", ""))
            if hits > 0:
                results.append((hits, f))

    # Sort by hits desc, then filename
    results.sort(key=lambda x: (-x[0], str(x[1].get("filename", ""))))
    # Return unpaged list
    # Add source info
    source_by_id = {s.get("id"): s for s in sources if isinstance(s, dict) and s.get("id")}
    out = []
    for hits, f in results:
        s = source_by_id.get(f.get("source_id"), {}) or {}
        out.append({
            "source_type": s.get("source_type"),
            "source_key": s.get("key"),
            "display_name": s.get("display_name"),
            "filename": f.get("filename"),
            "title": f.get("title"),
            "category": f.get("category"),
            "hit_count": hits,
        })

    exec_ms = int((time.time() - t0) * 1000)

    # Log search query (observable dynamics)
    now = _now_iso()
    log_row = {
        "id": _ulid(),
        "query_text": q,
        "framework_source_id": framework_source_id,
        "include_external": include_external,
        "service_source_ids": None,  # tool has no services[] param; null means "all active services" when include_external
        "context_length": None,
        "tool_name": "search_laravel_docs",
        "result_count": len(out),
        "execution_ms": exec_ms,
        "created_at": now,
        "updated_at": now,
    }
    search_log.append(log_row)
    _save("search_queries.json", search_log)

    return {
        "data": out,
        "meta": {
            "query": q,
            "version": version,
            "include_external": include_external,
            "count": len(out),
            "execution_ms": exec_ms,
        }
    }

def update_laravel_docs(version=None, force=False, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _ulid():
        import os as _os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        ts = ms & ((1 << 48) - 1)
        rnd = int.from_bytes(_os.urandom(10), "big")
        val = (ts << 80) | rnd
        out = []
        for _ in range(26):
            out.append(alphabet[val & 31])
            val >>= 5
        return "".join(reversed(out))

    # Validate inputs
    if version is not None and not isinstance(version, str):
        return _err("VALIDATION_ERROR", "version must be a string or null")
    if version is not None:
        v = version.strip()
        if v == "":
            return _err("VALIDATION_ERROR", "version must not be empty")
        if not re.fullmatch(r"\d+\.(x|\d+)", v):
            return _err("VALIDATION_ERROR", "invalid version format; expected like '11.x' or '11.0'", version=version)
        version = v
    if not isinstance(force, bool):
        return _err("VALIDATION_ERROR", "force must be boolean")

    sources = _load("doc_sources.json")
    jobs = _load("sync_jobs.json")

    # Resolve framework sources to update
    active_framework = [s for s in sources if isinstance(s, dict) and s.get("source_type") == "framework" and s.get("status") in ("active", "error", "disabled")]
    # For syncing, we allow any existing framework sources; but "requested_source_id resolved by version"
    if version is not None:
        target_sources = [s for s in active_framework if s.get("key") == version]
        if not target_sources:
            return _err("NOT_FOUND", "requested framework version not present in cache metadata", version=version)
    else:
        target_sources = [s for s in active_framework if s.get("status") == "active"]
        if not target_sources:
            return _err("NOT_FOUND", "no active framework documentation sources to update")

    requested_source_id = target_sources[0].get("id") if version is not None else None

    now = _now_iso()
    job = {
        "id": _ulid(),
        "job_type": "framework_sync",
        "requested_source_id": requested_source_id,
        "requested_keys": None if version is not None else [s.get("key") for s in target_sources if s.get("key")],
        "force": force,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "result_summary": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("sync_jobs.json", jobs)

    # Transition queued -> running
    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = job["started_at"]
    _save("sync_jobs.json", jobs)

    # Offline implementation: we cannot actually fetch upstream.
    # Realistic behavior: if force=False and we have prior sync info, treat as no-op but successful;
    # if force=True, still cannot fetch; mark failed due to offline upstream.
    try:
        if force:
            raise RuntimeError("Upstream sync not available in offline datastore")
        # Succeed as idempotent no-op: update last_synced_at and latest_synced_commit only if absent
        updated_sources = 0
        for s in sources:
            if not isinstance(s, dict) or s.get("id") not in {ts.get("id") for ts in target_sources if ts.get("id")}:
                continue
            # Mark source active if it was error and we are "successfully synced"
            if s.get("status") == "error":
                # lifecycle: error -> active allowed
                s["status"] = "active"
                s["last_error"] = None
            # If already has timestamps/commit, leave as-is (idempotent)
            if not s.get("last_synced_at"):
                s["last_synced_at"] = _now_iso()
                updated_sources += 1
            if not s.get("latest_synced_commit"):
                # commit unknown offline; put a stable sentinel that indicates cached state
                s["latest_synced_commit"] = "local-cache"
                updated_sources += 1
            s["updated_at"] = _now_iso()
        _save("doc_sources.json", sources)

        summary = {
            "sources_requested": len(target_sources),
            "sources_updated": updated_sources,
            "files_added": 0,
            "files_updated": 0,
            "files_deleted": 0,
            "note": "Offline mode: upstream fetch skipped; metadata refreshed only when missing (idempotent no-op)."
        }

        job["status"] = "succeeded"
        job["finished_at"] = _now_iso()
        job["result_summary"] = summary
        job["updated_at"] = job["finished_at"]
        _save("sync_jobs.json", jobs)

        per_source = []
        by_id = {s.get("id"): s for s in sources if isinstance(s, dict) and s.get("id")}
        for ts in target_sources:
            s = by_id.get(ts.get("id"), ts)
            per_source.append({
                "source_id": s.get("id"),
                "version": s.get("key"),
                "status": s.get("status"),
                "last_synced_at": s.get("last_synced_at"),
                "latest_synced_commit": s.get("latest_synced_commit"),
            })

        return {
            "data": {
                "job": job,
                "sources": per_source,
                "summary": summary,
            }
        }
    except RuntimeError as e:
        # running -> failed
        msg = str(e) if str(e) else "sync failed"
        job["status"] = "failed"
        job["error_message"] = msg
        job["finished_at"] = _now_iso()
        job["updated_at"] = job["finished_at"]
        job["result_summary"] = {
            "sources_requested": len(target_sources),
            "sources_synced": 0,
            "files_added": 0,
            "files_updated": 0,
            "files_deleted": 0,
        }
        _save("sync_jobs.json", jobs)
        return _err("CONFLICT", "unable to sync upstream in offline mode", detail=msg, job_id=job["id"])

def laravel_docs_info(version=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Validate inputs
    if version is not None and not isinstance(version, str):
        return _err("VALIDATION_ERROR", "version must be a string or null")
    if version is not None:
        v = version.strip()
        if v == "":
            return _err("VALIDATION_ERROR", "version must not be empty")
        if not re.fullmatch(r"\d+\.(x|\d+)", v):
            return _err("VALIDATION_ERROR", "invalid version format; expected like '11.x' or '11.0'", version=version)
        version = v

    sources = _load("doc_sources.json")

    framework = [s for s in sources if isinstance(s, dict) and s.get("source_type") == "framework"]
    if version is not None:
        match = [s for s in framework if s.get("key") == version]
        if not match:
            return _err("NOT_FOUND", "requested framework version has no cached metadata", version=version)
        s = match[0]
        return {
            "data": {
                "source_type": s.get("source_type"),
                "version": s.get("key"),
                "display_name": s.get("display_name"),
                "repo_url": s.get("repo_url"),
                "default_branch": s.get("default_branch"),
                "latest_synced_commit": s.get("latest_synced_commit"),
                "last_synced_at": s.get("last_synced_at"),
                "status": s.get("status"),
                "last_error": s.get("last_error"),
                "created_at": s.get("created_at"),
                "updated_at": s.get("updated_at"),
            }
        }

    # Otherwise return all active framework sources with last_synced_at/latest_synced_commit
    active_framework = [s for s in framework if s.get("status") == "active"]
    # Semantic sort by key like "11.x" / "10.x"
    def _sem_key(k):
        if not isinstance(k, str):
            return (-1, -1)
        m = re.fullmatch(r"(\d+)\.(x|\d+)", k.strip())
        if not m:
            return (-1, -1)
        major = int(m.group(1))
        minor = 9999 if m.group(2) == "x" else int(m.group(2))
        return (major, minor)

    active_framework.sort(key=lambda s: _sem_key(s.get("key")), reverse=True)

    out = []
    for s in active_framework:
        out.append({
            "version": s.get("key"),
            "display_name": s.get("display_name"),
            "latest_synced_commit": s.get("latest_synced_commit"),
            "last_synced_at": s.get("last_synced_at"),
            "status": s.get("status"),
        })

    return {"data": {"framework_versions": out, "count": len(out)}}

def get_laravel_package_recommendations(use_case, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()

    # Validation
    if not isinstance(use_case, str):
        return _err("VALIDATION_ERROR", "use_case must be a string")
    use_case_raw = use_case
    use_case = use_case.strip()
    if not use_case:
        return _err("VALIDATION_ERROR", "use_case must not be blank")

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _norm_text(s):
        s = (s or "")
        if not isinstance(s, str):
            return ""
        s = s.strip().lower()
        s = re.sub(r"[^a-z0-9]+", " ", s)
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _tokenize(s):
        s = _norm_text(s)
        if not s:
            return []
        return [t for t in s.split(" ") if t]

    # Be permissive: if caller passes an ID-like string, treat it as plain text too.
    q_tokens = _tokenize(use_case)
    q_set = set(q_tokens)

    packages = _load("packages.json")
    # Only active packages per business rules
    active_pkgs = [p for p in packages if isinstance(p, dict) and p.get("status") == "active"]

    # If query is too "opaque" (e.g. ULID-ish) tokenize still yields tokens; scoring will likely be 0.
    # In that case, fall back to returning a curated "top" set (still active only) rather than error,
    # because the tool can "produce recommendations" even when not text-matched.
    def _pkg_hay(pkg):
        parts = []
        for k in ("package_name", "display_name", "category", "description"):
            v = pkg.get(k)
            if isinstance(v, str) and v.strip():
                parts.append(v)
        cu = pkg.get("common_use_cases")
        if isinstance(cu, list):
            for v in cu:
                if isinstance(v, str) and v.strip():
                    parts.append(v)
        return _norm_text(" ".join(parts))

    def _score_pkg(pkg):
        hay = _pkg_hay(pkg)
        if not hay or not q_set:
            return 0, []
        hay_tokens = set(_tokenize(hay))
        hits = [t for t in q_set if t in hay_tokens]
        if not hits:
            return 0, []
        # light weighting
        cat_tokens = set(_tokenize(pkg.get("category") or ""))
        name_tokens = set(_tokenize(pkg.get("package_name") or ""))
        desc_tokens = set(_tokenize(pkg.get("description") or ""))
        score = 0
        for t in hits:
            score += 3 if t in cat_tokens else 0
            score += 2 if t in name_tokens else 0
            score += 1 if t in desc_tokens else 0
            score += 1
        return score, hits[:25]

    scored = []
    for p in active_pkgs:
        score, hits = _score_pkg(p)
        if score > 0:
            scored.append((score, hits, p))

    # Sort by score desc, then stable by package_name
    scored.sort(key=lambda x: (-x[0], (x[2].get("package_name") or "")))

    results = []
    if scored:
        top = scored[:10]
        for score, hits, p in top:
            results.append({
                "package_name": p.get("package_name"),
                "display_name": p.get("display_name"),
                "category": p.get("category"),
                "description": p.get("description"),
                "homepage_url": p.get("homepage_url"),
                "repository_url": p.get("repository_url"),
                "installation": p.get("installation"),
                "rationale": {
                    "score": score,
                    "matched_terms": hits
                }
            })
    else:
        # Fallback: return up to 10 active packages, category-diversified (best-effort),
        # so the tool returns data rather than NOT_FOUND for poorly-matching text.
        # Deterministic ordering: category then package_name.
        by_cat = {}
        for p in active_pkgs:
            cat = p.get("category") if isinstance(p.get("category"), str) else "other"
            by_cat.setdefault(cat.lower(), []).append(p)
        for cat in by_cat:
            by_cat[cat].sort(key=lambda p: (p.get("package_name") or ""))
        for cat in sorted(by_cat.keys()):
            if len(results) >= 10:
                break
            for p in by_cat[cat]:
                if len(results) >= 10:
                    break
                results.append({
                    "package_name": p.get("package_name"),
                    "display_name": p.get("display_name"),
                    "category": p.get("category"),
                    "description": p.get("description"),
                    "homepage_url": p.get("homepage_url"),
                    "repository_url": p.get("repository_url"),
                    "installation": p.get("installation"),
                    "rationale": {
                        "score": 0,
                        "matched_terms": [],
                        "note": "No direct text matches for the provided use_case; returning a general curated set of active packages."
                    }
                })

    # Must never raise NOT_FOUND for empty matches if we can produce recommendations;
    # but if there are literally no active packages, then NOT_FOUND is appropriate.
    if not results:
        return _err("NOT_FOUND", "No active packages available for recommendations")

    return {
        "use_case": use_case_raw,
        "count": len(results),
        "packages": results
    }

def get_laravel_package_info(package_name, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")

    def _load(n):
