def read_laravel_doc_content(filename, version=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid():
        # Deterministic-enough, sortable id without external deps
        t_ms = int(time.time() * 1000)
        rand = os.urandom(10)
        return f"01{t_ms:010x}{rand.hex()}"[:26]

    def _semver_key(v):
        # Accept things like "11.x", "10.x", "9.x", "11", "11.0", "11.2"
        if not isinstance(v, str):
            return None
        s = v.strip().lower()
        if not s:
            return None
        m = re.match(r"^(\d+)(?:\.(\d+))?(?:\.(\d+))?(?:\.x|x)?$", s)
        if not m:
            return None
        a = int(m.group(1))
        b = int(m.group(2) or 0)
        c = int(m.group(3) or 0)
        # prefer explicit patch/minor over implied .x
        explicit = 1 if (m.group(2) is not None or m.group(3) is not None) else 0
        return (a, b, c, explicit)

    def _log_search(tool_name, query_text, framework_source_id, include_external, service_source_ids, context_length, result_count, execution_ms):
        # Observability: log in search_queries for *every* call we implement
        rows = _load("search_queries.json")
        ts = _now()
        row = {
            "id": _ulid(),
            "query_text": query_text,
            "framework_source_id": framework_source_id,
            "include_external": bool(include_external),
            "service_source_ids": service_source_ids,
            "context_length": context_length,
            "tool_name": tool_name,
            "result_count": int(result_count),
            "execution_ms": int(execution_ms),
            "created_at": ts,
            "updated_at": ts,
        }
        rows.append(row)
        _save("search_queries.json", rows)

    t0 = time.time()

    # Validate filename
    if not isinstance(filename, str) or not filename.strip():
        ms = int((time.time() - t0) * 1000)
        _log_search("read_laravel_doc_content", "", None, False, None, None, 0, ms)
        return _err("VALIDATION_ERROR", "filename must be a non-empty string")

    filename = filename.strip()

    # Validate version if provided
    if version is not None and (not isinstance(version, str) or not version.strip()):
        ms = int((time.time() - t0) * 1000)
        _log_search("read_laravel_doc_content", "", None, False, None, None, 0, ms)
        return _err("VALIDATION_ERROR", "version must be a string or null")

    version_key = version.strip() if isinstance(version, str) else None
    if version_key is not None and _semver_key(version_key) is None:
        ms = int((time.time() - t0) * 1000)
        _log_search("read_laravel_doc_content", "", None, False, None, None, 0, ms)
        return _err("VALIDATION_ERROR", "version is invalid or not supported by semantic parsing", version=version_key)

    sources = _load("doc_sources.json")
    files = _load("doc_files.json")

    # Resolve framework source
    framework_sources = [s for s in sources if s.get("source_type") == "framework" and s.get("status") == "active"]
    if version_key is not None:
        framework_sources = [s for s in framework_sources if s.get("key") == version_key]
        if not framework_sources:
            ms = int((time.time() - t0) * 1000)
            _log_search("read_laravel_doc_content", "", None, False, None, None, 0, ms)
            return _err("NOT_FOUND", "framework version not found", version=version_key)
        src = framework_sources[0]
    else:
        if not framework_sources:
            ms = int((time.time() - t0) * 1000)
            _log_search("read_laravel_doc_content", "", None, False, None, None, 0, ms)
            return _err("NOT_FOUND", "no active framework documentation sources available")
        # choose newest by semantic sort of key
        scored = []
        for s in framework_sources:
            k = s.get("key")
            sk = _semver_key(k) if isinstance(k, str) else None
            if sk is not None:
                scored.append((sk, s))
        if not scored:
            # fallback: latest updated
            src = sorted(framework_sources, key=lambda x: x.get("updated_at") or "", reverse=True)[0]
        else:
            src = sorted(scored, key=lambda x: x[0], reverse=True)[0][1]

    # Find active file for that source
    match = None
    for f in files:
        if f.get("source_id") == src.get("id") and f.get("filename") == filename and f.get("status") == "active":
            match = f
            break
    if not match:
        ms = int((time.time() - t0) * 1000)
        _log_search("read_laravel_doc_content", "", src.get("id"), False, None, None, 0, ms)
        return _err("NOT_FOUND", "documentation file not found for requested version", version=src.get("key"), filename=filename)

    ms = int((time.time() - t0) * 1000)
    _log_search("read_laravel_doc_content", "", src.get("id"), False, None, None, 1, ms)

    return {
        "source": {
            "id": src.get("id"),
            "key": src.get("key"),
            "display_name": src.get("display_name"),
            "source_type": src.get("source_type"),
            "latest_synced_commit": src.get("latest_synced_commit"),
            "last_synced_at": src.get("last_synced_at"),
            "status": src.get("status"),
            "last_error": src.get("last_error"),
        },
        "doc": {
            "id": match.get("id"),
            "source_id": match.get("source_id"),
            "filename": match.get("filename"),
            "category": match.get("category"),
            "title": match.get("title"),
            "content_markdown": match.get("content_markdown"),
            "word_count": match.get("word_count"),
            "status": match.get("status"),
            "updated_at": match.get("updated_at"),
        },
    }

def search_laravel_docs_with_context(query, version=None, context_length=200, include_external=True, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid():
        t_ms = int(time.time() * 1000)
        rand = os.urandom(10)
        return f"01{t_ms:010x}{rand.hex()}"[:26]

    def _semver_key(v):
        if not isinstance(v, str):
            return None
        s = v.strip().lower()
        if not s:
            return None
        m = re.match(r"^(\d+)(?:\.(\d+))?(?:\.(\d+))?(?:\.x|x)?$", s)
        if not m:
            return None
        a = int(m.group(1))
        b = int(m.group(2) or 0)
        c = int(m.group(3) or 0)
        explicit = 1 if (m.group(2) is not None or m.group(3) is not None) else 0
        return (a, b, c, explicit)

    def _log(tool_name, query_text, framework_source_id, include_external_v, service_source_ids, context_length_v, result_count, execution_ms):
        rows = _load("search_queries.json")
        ts = _now()
        row = {
            "id": _ulid(),
            "query_text": query_text,
            "framework_source_id": framework_source_id,
            "include_external": bool(include_external_v),
            "service_source_ids": service_source_ids,
            "context_length": context_length_v,
            "tool_name": tool_name,
            "result_count": int(result_count),
            "execution_ms": int(execution_ms),
            "created_at": ts,
            "updated_at": ts,
        }
        rows.append(row)
        _save("search_queries.json", rows)

    def _normalize(s):
        return (s or "").lower()

    def _find_snippet(text, q, ctx_len):
        if text is None:
            return ""
        t = text
        t_l = t.lower()
        q_l = q.lower()
        idx = t_l.find(q_l)
        if idx < 0:
            # fallback: first ctx_len chars
            return t[:ctx_len] if ctx_len is not None else t
        start = max(0, idx - ctx_len // 2)
        end = min(len(t), start + ctx_len)
        snippet = t[start:end]
        return snippet

    t0 = time.time()

    # Validate query
    if not isinstance(query, str) or not query.strip():
        ms = int((time.time() - t0) * 1000)
        _log("search_laravel_docs_with_context", query if isinstance(query, str) else "", None, bool(include_external), None, context_length, 0, ms)
        return _err("VALIDATION_ERROR", "query must be a non-empty string")

    query = query.strip()
    if len(query) > 2048:
        ms = int((time.time() - t0) * 1000)
        _log("search_laravel_docs_with_context", query, None, bool(include_external), None, context_length, 0, ms)
        return _err("VALIDATION_ERROR", "query must be between 1 and 2048 characters")

    # Validate context_length
    if not isinstance(context_length, int):
        ms = int((time.time() - t0) * 1000)
        _log("search_laravel_docs_with_context", query, None, bool(include_external), None, None, 0, ms)
        return _err("VALIDATION_ERROR", "context_length must be an integer")
    if context_length < 0 or context_length > 5000:
        ms = int((time.time() - t0) * 1000)
        _log("search_laravel_docs_with_context", query, None, bool(include_external), None, context_length, 0, ms)
        return _err("VALIDATION_ERROR", "context_length must be between 0 and 5000", context_length=context_length)

    if include_external is None:
        include_external = True
    if not isinstance(include_external, bool):
        ms = int((time.time() - t0) * 1000)
        _log("search_laravel_docs_with_context", query, None, True, None, context_length, 0, ms)
        return _err("VALIDATION_ERROR", "include_external must be a boolean")

    # Validate version if provided
    if version is not None and (not isinstance(version, str) or not version.strip()):
        ms = int((time.time() - t0) * 1000)
        _log("search_laravel_docs_with_context", query, None, include_external, None, context_length, 0, ms)
        return _err("VALIDATION_ERROR", "version must be a string or null")
    version_key = version.strip() if isinstance(version, str) else None
    if version_key is not None and _semver_key(version_key) is None:
        ms = int((time.time() - t0) * 1000)
        _log("search_laravel_docs_with_context", query, None, include_external, None, context_length, 0, ms)
        return _err("VALIDATION_ERROR", "version is invalid or not supported by semantic parsing", version=version_key)

    sources = _load("doc_sources.json")
    files = _load("doc_files.json")

    # Resolve framework scope
    framework_sources = [s for s in sources if s.get("source_type") == "framework" and s.get("status") == "active"]
    framework_source_id = None
    framework_source_ids = []
    if version_key is not None:
        fw = [s for s in framework_sources if s.get("key") == version_key]
        if not fw:
            ms = int((time.time() - t0) * 1000)
            _log("search_laravel_docs_with_context", query, None, include_external, None, context_length, 0, ms)
            return _err("NOT_FOUND", "framework version not found", version=version_key)
        framework_source_id = fw[0].get("id")
        framework_source_ids = [framework_source_id]
    else:
        framework_source_ids = [s.get("id") for s in framework_sources if s.get("id")]
        # For logging, store null for "all active framework versions"
        framework_source_id = None

    # Resolve service scope
    service_sources = []
    service_source_ids = None
    if include_external:
        service_sources = [s for s in sources if s.get("source_type") == "service" and s.get("status") == "active"]
        service_source_ids = [s.get("id") for s in service_sources if s.get("id")]

    ql = query.lower()

    # Search: simple substring match; rank by hit position then shorter doc then filename
    candidates = []
    for f in files:
        if f.get("status") != "active":
            continue
        sid = f.get("source_id")
        if sid in framework_source_ids:
            pass
        elif include_external and sid in (service_source_ids or []):
            pass
        else:
            continue

        content = f.get("content_markdown") or ""
        content_l = content.lower()
        idx = content_l.find(ql)
        title = f.get("title") or ""
        fn = f.get("filename") or ""
        cat = f.get("category")
        # also search title/filename/category to allow hits even if content missing
        idx2 = (title.lower().find(ql) if title else -1)
        idx3 = (fn.lower().find(ql) if fn else -1)
        idx4 = ((cat or "").lower().find(ql) if cat else -1)

        best = min([x for x in [idx, idx2, idx3, idx4] if x >= 0], default=-1)
        if best < 0:
            continue

        snippet_source = content if idx >= 0 else (title if idx2 >= 0 else (fn if idx3 >= 0 else (cat or "")))
        snippet = _find_snippet(snippet_source, query, context_length)

        candidates.append((best, len(content), fn, f, snippet))

    candidates.sort(key=lambda x: (x[0], x[1], x[2]))

    # Build source lookup for output
    src_by_id = {s.get("id"): s for s in sources if s.get("id")}

    results = []
    for _, _, _, f, snippet in candidates:
        s = src_by_id.get(f.get("source_id")) or {}
        results.append(
            {
                "source": {
                    "id": s.get("id"),
                    "source_type": s.get("source_type"),
                    "key": s.get("key"),
                    "display_name": s.get("display_name"),
                },
                "doc": {
                    "id": f.get("id"),
                    "source_id": f.get("source_id"),
                    "filename": f.get("filename"),
                    "title": f.get("title"),
                    "category": f.get("category"),
                    "word_count": f.get("word_count"),
                },
                "context": snippet,
            }
        )

    ms = int((time.time() - t0) * 1000)
    _log("search_laravel_docs_with_context", query, framework_source_id, include_external, service_source_ids, context_length, len(results), ms)

    return {
        "query": query,
        "version": version_key,
        "include_external": include_external,
        "context_length": context_length,
        "result_count": len(results),
        "results": results,
        "meta": {"execution_ms": ms},
    }

def get_doc_structure(filename, version=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _validate_filename(fn):
        if not _is_nonempty_str(fn):
            return False, "filename must be a non-empty string"
        fn = fn.strip()
        if len(fn) > 512:
            return False, "filename is too long"
        if fn.startswith("/") or fn.startswith("\\"):
            return False, "filename must be a relative path"
        if "\x00" in fn:
            return False, "filename contains invalid characters"
        # Basic path safety: no traversal segments
        parts = re.split(r"[\\/]+", fn)
        if any(p in ("..", ".") for p in parts):
            return False, "filename contains invalid path segments"
        return True, None

    def _parse_semverish_key(k):
        # For framework keys like "11.x" or "10.x"; treat as (major, minor)
        if not isinstance(k, str):
            return None
        m = re.match(r"^\s*(\d+)(?:\.(\d+))?\.x\s*$", k)
        if m:
            major = int(m.group(1))
            minor = int(m.group(2) or 0)
            return (major, minor, k.strip())
        m2 = re.match(r"^\s*(\d+)(?:\.(\d+))?\s*$", k)
        if m2:
            major = int(m2.group(1))
            minor = int(m2.group(2) or 0)
            return (major, minor, k.strip())
        return None

    def _choose_framework_source(doc_sources, version_key):
        framework_active = [s for s in doc_sources if s.get("source_type") == "framework" and s.get("status") == "active"]
        if version_key is None:
            if not framework_active:
                return None, None
            # semantic sort descending by key
            scored = []
            for s in framework_active:
                sc = _parse_semverish_key(s.get("key"))
                if sc is None:
                    # deprioritize unknown formats but keep stable ordering
                    scored.append((( -1, -1, str(s.get("key") or "")), s))
                else:
                    scored.append(((sc[0], sc[1], sc[2]), s))
            scored.sort(key=lambda t: (t[0][0], t[0][1], t[0][2]), reverse=True)
            return scored[0][1], None
        # version provided
        if not isinstance(version_key, str):
            return None, _err("VALIDATION_ERROR", "version must be a string or null")
        version_key = version_key.strip()
        if version_key == "":
            return None, _err("VALIDATION_ERROR", "version must be a non-empty string or null")
        matches = [s for s in framework_active if s.get("key") == version_key]
        if not matches:
            return None, _err("VALIDATION_ERROR", "version is not supported", version=version_key)
        return matches[0], None

    def _parse_sections_from_markdown(md):
        # Return list of nodes: {"level": int, "text": str, "anchor": str}
        if not isinstance(md, str):
            md = ""

        lines = md.splitlines()
        sections = []

        in_fenced = False
        fence_pat = re.compile(r"^\s*(|~~~)")
        heading_pat = re.compile(r"^\s{0,3}(#{1,6})\s+(.*?)\s*(?:#+\s*)?$")

        def slugify(text):
            t = text.strip().lower()
            # remove markdown links/images formatting
            t = re.sub(r"!\[([^\]]*)\]\([^)]+\)", r"\1", t)
            t = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", t)
            # remove inline code/backticks
            t = t.replace("`", "")
            # remove html tags
            t = re.sub(r"<[^>]+>", "", t)
            # keep alnum, spaces, hyphens; collapse spaces to hyphens
            t = re.sub(r"[^a-z0-9\s-]", "", t)
            t = re.sub(r"\s+", "-", t).strip("-")
            return t or "section"

        seen = {}
        for line in lines:
            if fence_pat.match(line):
                in_fenced = not in_fenced
                continue
            if in_fenced:
                continue
            m = heading_pat.match(line)
            if not m:
                continue
            level = len(m.group(1))
            text = m.group(2).strip()
            if not text:
                continue
            base = slugify(text)
            cnt = seen.get(base, 0)
            seen[base] = cnt + 1
            anchor = base if cnt == 0 else f"{base}-{cnt+1}"
            sections.append({"level": level, "text": text, "anchor": anchor})
        return sections

    t0 = time.time()

    # Validate inputs
    ok_fn, fn_msg = _validate_filename(filename)
    if not ok_fn:
        return _err("VALIDATION_ERROR", fn_msg)

    if version is not None and not isinstance(version, str):
        return _err("VALIDATION_ERROR", "version must be a string or null")

    # Load datastore
    doc_sources = _load("doc_sources.json")
    doc_files = _load("doc_files.json")

    # Resolve framework source (active) by version or newest
    source, verr = _choose_framework_source(doc_sources, version)
    if verr is not None:
        return verr
    if source is None:
        return _err("NOT_FOUND", "No active framework documentation source is available")

    # Find active doc file
    fn = filename.strip()
    file_row = None
    for f in doc_files:
        if f.get("source_id") == source.get("id") and f.get("filename") == fn:
            file_row = f
            break

    if file_row is None:
        return _err("NOT_FOUND", "Documentation file not found for the requested version", filename=fn, version=source.get("key"))
    if file_row.get("status") != "active" and file_row.get("status") != "stale":
        # The tool description says NOT_FOUND if file doesn't exist; treat non-readable states as not found
        return _err("NOT_FOUND", "Documentation file not available", filename=fn, version=source.get("key"))

    # Parse/refresh sections if needed
    needs_parse = file_row.get("sections") is None or file_row.get("status") == "stale"
    mutated = False
    if needs_parse:
        sections = _parse_sections_from_markdown(file_row.get("content_markdown", ""))
        file_row["sections"] = sections
        # If it was stale, move it back to active per lifecycle rules (stale -> active is legal)
        if file_row.get("status") == "stale":
            file_row["status"] = "active"
        now = _now_iso()
        file_row["updated_at"] = now
        # business rule: update last_indexed_at as appropriate
        file_row["last_indexed_at"] = now
        mutated = True

    if mutated:
        _save("doc_files.json", doc_files)

    elapsed_ms = int((time.time() - t0) * 1000)

    return {
        "source": {
            "id": source.get("id"),
            "key": source.get("key"),
            "display_name": source.get("display_name"),
        },
        "file": {
            "id": file_row.get("id"),
            "filename": file_row.get("filename"),
            "title": file_row.get("title"),
            "category": file_row.get("category"),
            "status": file_row.get("status"),
            "updated_at": file_row.get("updated_at"),
            "last_indexed_at": file_row.get("last_indexed_at"),
            "word_count": file_row.get("word_count"),
        },
        "sections": file_row.get("sections") or [],
        "meta": {
            "parsed": bool(needs_parse),
            "execution_ms": elapsed_ms,
        },
    }

def browse_docs_by_category(category, version=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid():
        t_ms = int(time.time() * 1000)
        rand = os.urandom(10)
        return f"01{t_ms:010x}{rand.hex()}"[:26]

    def _semver_key(v):
        if not isinstance(v, str):
            return None
        s = v.strip().lower()
        if not s:
            return None
        m = re.match(r"^(\d+)(?:\.(\d+))?(?:\.(\d+))?(?:\.x|x)?$", s)
        if not m:
            return None
        a = int(m.group(1))
        b = int(m.group(2) or 0)
        c = int(m.group(3) or 0)
        explicit = 1 if (m.group(2) is not None or m.group(3) is not None) else 0
        return (a, b, c, explicit)

    def _log_search(tool_name, query_text, framework_source_id, include_external, service_source_ids, context_length, result_count, execution_ms):
        rows = _load("search_queries.json")
        ts = _now()
        row = {
            "id": _ulid(),
            "query_text": query_text,
            "framework_source_id": framework_source_id,
            "include_external": bool(include_external),
            "service_source_ids": service_source_ids,
            "context_length": context_length,
            "tool_name": tool_name,
            "result_count": int(result_count),
            "execution_ms": int(execution_ms),
            "created_at": ts,
            "updated_at": ts,
        }
        rows.append(row)
        _save("search_queries.json", rows)

    t0 = time.time()

    if not isinstance(category, str) or not category.strip():
        ms = int((time.time() - t0) * 1000)
        _log_search("browse_docs_by_category", "", None, False, None, None, 0, ms)
        return _err("VALIDATION_ERROR", "category must be a non-empty string")
    category = category.strip()

    if version is not None and (not isinstance(version, str) or not version.strip()):
        ms = int((time.time() - t0) * 1000)
        _log_search("browse_docs_by_category", "", None, False, None, None, 0, ms)
        return _err("VALIDATION_ERROR", "version must be a string or null")

    version_key = version.strip() if isinstance(version, str) else None
    if version_key is not None and _semver_key(version_key) is None:
        ms = int((time.time() - t0) * 1000)
        _log_search("browse_docs_by_category", "", None, False, None, None, 0, ms)
        return _err("VALIDATION_ERROR", "version is invalid or not supported by semantic parsing", version=version_key)

    sources = _load("doc_sources.json")
    files = _load("doc_files.json")

    framework_sources = [s for s in sources if s.get("source_type") == "framework" and s.get("status") == "active"]
    if version_key is not None:
        fw = [s for s in framework_sources if s.get("key") == version_key]
        if not fw:
            ms = int((time.time() - t0) * 1000)
            _log_search("browse_docs_by_category", "", None, False, None, None, 0, ms)
            return _err("NOT_FOUND", "framework version not found", version=version_key)
        src = fw[0]
    else:
        if not framework_sources:
            ms = int((time.time() - t0) * 1000)
            _log_search("browse_docs_by_category", "", None, False, None, None, 0, ms)
            return _err("NOT_FOUND", "no active framework documentation sources available")
        scored = []
        for s in framework_sources:
            sk = _semver_key(s.get("key") if isinstance(s.get("key"), str) else "")
            if sk is not None:
                scored.append((sk, s))
        src = (sorted(scored, key=lambda x: x[0], reverse=True)[0][1]) if scored else sorted(framework_sources, key=lambda x: x.get("updated_at") or "", reverse=True)[0]

    # Filter active files by category (exact match)
    items = []
    for f in files:
        if f.get("status") != "active":
            continue
        if f.get("source_id") != src.get("id"):
            continue
        if (f.get("category") or "") != category:
            continue
        items.append(f)

    # Sort in "browse order": category then filename
    items.sort(key=lambda x: (x.get("title") or "", x.get("filename") or ""))

    if not items:
        ms = int((time.time() - t0) * 1000)
        _log_search("browse_docs_by_category", "", src.get("id"), False, None, None, 0, ms)
        return _err("NOT_FOUND", "no documents found for category in requested version", category=category, version=src.get("key"))

    results = []
    for f in items:
        results.append(
            {
                "id": f.get("id"),
                "filename": f.get("filename"),
                "title": f.get("title"),
                "category": f.get("category"),
                "word_count": f.get("word_count"),
                "updated_at": f.get("updated_at"),
            }
        )

    ms = int((time.time() - t0) * 1000)
    _log_search("browse_docs_by_category", "", src.get("id"), False, None, None, len(results), ms)

    return {
        "category": category,
        "version": src.get("key"),
        "source": {"id": src.get("id"), "display_name": src.get("display_name"), "key": src.get("key")},
        "result_count": len(results),
        "docs": results,
        "meta": {"execution_ms": ms},
    }

def list_laravel_services(status=None, key=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _dt_parse(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Validate
    allowed_status = {"active", "disabled", "error"}
    allowed_sort = {"display_name", "key", "last_synced_at", "created_at", "updated_at"}
    allowed_order = {"asc", "desc"}

    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "Invalid status", allowed=list(sorted(allowed_status)))
    if sort is None:
        sort = "display_name"
    if sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "Invalid sort field", allowed=list(sorted(allowed_sort)))
    if order is None:
        order = "asc"
    if order not in allowed_order:
        return _err("VALIDATION_ERROR", "Invalid order", allowed=list(sorted(allowed_order)))
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if key is not None and (not isinstance(key, str) or not key.strip()):
        return _err("VALIDATION_ERROR", "key must be a non-empty string when provided")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string or null")

    # Decode cursor
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("o:"):
                return _err("VALIDATION_ERROR", "Malformed cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Malformed cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Malformed cursor")

    # Load and filter
    doc_sources = _load("doc_sources.json")
    rows = [r for r in doc_sources if r.get("source_type") == "service"]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if key is not None:
        k = key.strip()
        rows = [r for r in rows if r.get("key") == k]

    # Sort
    reverse = (order == "desc")

    def sort_key(r):
        v = r.get(sort)
        if sort in ("created_at", "updated_at", "last_synced_at"):
            dt = _dt_parse(v)
            # None sorts last in asc, first in desc
            if dt is None:
                return (1, datetime.datetime.min) if not reverse else (0, datetime.datetime.min)
            return (0, dt)
        if v is None:
            return ""
        return str(v).lower() if isinstance(v, str) else str(v)

    try:
        rows.sort(key=sort_key, reverse=reverse)
    except Exception:
        # If sort fails due to unexpected types, return validation-ish error object (no raise)
        return _err("CONFLICT", "Unable to sort results due to invalid stored data")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"o:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Response envelope
    items = []
    for r in page:
        items.append(
            {
                "id": r.get("id"),
                "key": r.get("key"),
                "display_name": r.get("display_name"),
                "status": r.get("status"),
                "docs_base_url": r.get("docs_base_url"),
                "repo_url": r.get("repo_url"),
                "default_branch": r.get("default_branch"),
                "latest_synced_commit": r.get("latest_synced_commit"),
                "last_synced_at": r.get("last_synced_at"),
                "last_error": r.get("last_error"),
                "created_at": r.get("created_at"),
                "updated_at": r.get("updated_at"),
            }
        )

    return {
        "data": items,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
            "offset": offset,
        },
    }

def search_external_laravel_docs(query, services=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _ulid():
        ts_ms = int(time.time() * 1000)
        v = ts_ms & ((1 << 48) - 1)
        tchars = []
        for _ in range(10):
            tchars.append(_CROCKFORD[v & 31])
            v >>= 5
        t = "".join(reversed(tchars))
        rb = os.urandom(10)
        r = int.from_bytes(rb, "big")
        rchars = []
        for _ in range(16):
            rchars.append(_CROCKFORD[r & 31])
            r >>= 5
        return t + "".join(reversed(rchars))

    # Validation
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    q = query.strip()
    if len(q) > 2048:
        return _err("VALIDATION_ERROR", "query is too long (max 2048)")
    if services is not None:
        if not isinstance(services, list) or any(not isinstance(s, str) for s in services):
            return _err("VALIDATION_ERROR", "services must be an array of strings or null")
        norm = []
        for s in services:
            ss = s.strip()
            if not ss:
                return _err("VALIDATION_ERROR", "services contains an empty key")
            norm.append(ss)
        services = norm

    t0 = time.time()
    doc_sources = _load("doc_sources.json")
    doc_files = _load("doc_files.json")
    search_queries = _load("search_queries.json")

    # Resolve service sources
    service_sources = [r for r in doc_sources if r.get("source_type") == "service"]
    known_keys = {r.get("key") for r in service_sources}
    if services is not None:
        unknown = [k for k in services if k not in known_keys]
        if unknown:
            return _err("VALIDATION_ERROR", "Unknown service key(s)", unknown_keys=unknown)
        scoped_sources = [r for r in service_sources if r.get("key") in set(services)]
        if not scoped_sources:
            return _err("NOT_FOUND", "None of the requested services exist")
    else:
        scoped_sources = [r for r in service_sources]

    # Only active doc_files for active service sources
    active_source_ids = {r.get("id") for r in scoped_sources if r.get("status") == "active"}
    # If user explicitly requested services but they are all non-active, still return empty set (read should not error).
    candidates = [
        f for f in doc_files
        if f.get("source_id") in active_source_ids and f.get("status") == "active" and isinstance(f.get("content_markdown"), str)
    ]

    # Search: simple token scoring with section bonus
    tokens = [t for t in re.split(r"\s+", q.lower()) if t]
    if not tokens:
        return _err("VALIDATION_ERROR", "query must contain searchable characters")

    def score_doc(text, title):
        text_l = text.lower()
        title_l = (title or "").lower()
        s = 0
        for tok in tokens:
            if not tok:
                continue
            # frequency (capped)
            cnt = text_l.count(tok)
            s += min(cnt, 20)
            if tok in title_l:
                s += 10
        return s

    results = []
    for f in candidates:
        s = score_doc(f.get("content_markdown", ""), f.get("title"))
        if s <= 0:
            continue
        # Produce a minimal match snippet around first token
        content = f.get("content_markdown", "")
        content_l = content.lower()
        idx = -1
        for tok in tokens:
            idx = content_l.find(tok)
            if idx != -1:
                break
        snippet = None
        if idx != -1:
            start = max(0, idx - 120)
            end = min(len(content), idx + 180)
            snippet = content[start:end]
        results.append(
            {
                "doc_file_id": f.get("id"),
                "source_id": f.get("source_id"),
                "filename": f.get("filename"),
                "title": f.get("title"),
                "category": f.get("category"),
                "score": s,
                "snippet": snippet,
            }
        )

    results.sort(key=lambda r: (r["score"], r.get("title") or "", r.get("filename") or ""), reverse=True)

    elapsed_ms = int((time.time() - t0) * 1000)

    # Log search_queries row
    # tool_name='search_external_laravel_docs', include_external=true (external only but included), framework_source_id null
    service_ids_logged = [r.get("id") for r in scoped_sources] if services is not None else None
    now = _now()
    sq = {
        "id": _ulid(),
        "query_text": q,
        "framework_source_id": None,
        "include_external": True,
        "service_source_ids": service_ids_logged,
        "context_length": None,
        "tool_name": "search_external_laravel_docs",
        "result_count": len(results),
        "execution_ms": elapsed_ms if elapsed_ms >= 0 else 0,
        "created_at": now,
        "updated_at": now,
    }
    search_queries.append(sq)
    _save("search_queries.json", search_queries)

    return {
        "data": results,
        "meta": {
            "query": q,
            "services": services,
            "result_count": len(results),
            "execution_ms": elapsed_ms,
            "search_query_id": sq["id"],
        },
    }

def get_laravel_service_info(service, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0390000" if __import__("os").path.isdir("./environment_mix/0390000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _as_rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _save_same_shape(filename, loaded_obj, rows):
        if isinstance(loaded_obj, dict) and isinstance(loaded_obj.get("rows"), list):
            loaded_obj["rows"] = rows
            _save(filename, loaded_obj)
        else:
            _save(filename, rows)

    def _ulid(prefix):
        # Deterministic-ish, sortable enough for local store usage
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}_{ts}"

    def _log_search(status_code, result_count, exec_ms, service_source_ids=None):
        # The datastore uses search_queries as the observable request log.
        # For this tool, log as search_external_laravel_docs (closest available enum).
        sq_loaded = _load("search_queries.json")
        sq_rows = _as_rows(sq_loaded)
        now = _iso_now()
        sq_rows.append({
            "id": _ulid("lmc_qry"),
            "query_text": f"get_laravel_service_info:{service}",
            "framework_source_id": None,
            "include_external": True,
            "service_source_ids": service_source_ids,
            "context_length": None,
            "tool_name": "search_external_laravel_docs",
            "result_count": int(result_count) if isinstance(result_count, int) and result_count >= 0 else 0,
            "execution_ms": int(exec_ms) if isinstance(exec_ms, int) and exec_ms >= 0 else 0,
            "created_at": now,
            "updated_at": now,
            "status_code": status_code,  # extra field tolerated by local store
        })
        _save_same_shape("search_queries.json", sq_loaded, sq_rows)

    # ---- Validation ----
    if not isinstance(service, str) or not service.strip():
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log_search("VALIDATION_ERROR", 0, max(0, latency), service_source_ids=None)
        return _err("VALIDATION_ERROR", "service must be a non-empty string", service=service)

    service = service.strip()

    # ---- Resolve service source ----
    ds_loaded = _load("doc_sources.json")
    ds_rows = _as_rows(ds_loaded)

    # Accept either the service "key" (e.g. forge) OR the doc_sources "id"
    matches = []
    for r in ds_rows:
        if not isinstance(r, dict):
            continue
        if r.get("source_type") != "service":
            continue
        if r.get("key") == service or r.get("id") == service:
            matches.append(r)

    # If none matched as a service, but the caller passed a real doc_sources id that is NOT a service,
    # treat it as not found (not validation error), matching vendor behavior expectation.
    if not matches:
        latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        _log_search("NOT_FOUND", 0, max(0, latency), service_source_ids=None)
        return _err("NOT_FOUND", "Service not recognized", service=service)

    # Prefer active, else return any match (disabled/error still "recognized")
    def _status_rank(s):
        return {"active": 0, "disabled": 1, "error": 2}.get(s, 9)

    src = sorted(matches, key=lambda r: (_status_rank(r.get("status")), r.get("key") or "", r.get("id") or ""))[0]

    # ---- Derived info: latest sync job for this source ----
    sj_loaded = _load("sync_jobs.json")
    sj_rows = _as_rows(sj_loaded)

    latest_job = None
    latest_job_dt = None
    for j in sj_rows:
        if not isinstance(j, dict):
            continue
        if j.get("job_type") != "service_sync":
            continue

        # job may point to source via requested_source_id or via requested_keys array
        requested_source_id = j.get("requested_source_id")
        requested_keys = j.get("requested_keys")

        targets = False
        if requested_source_id and requested_source_id == src.get("id"):
            targets = True
        elif isinstance(requested_keys, list) and src.get("key") in requested_keys:
            targets = True

        if not targets:
            continue

        # choose by created_at then updated_at then id
        cand_dt = None
        for fld in ("created_at", "updated_at", "started_at", "finished_at"):
            v = j.get(fld)
            if isinstance(v, str) and v:
                try:
                    cand_dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
                    break
                except Exception:
                    cand_dt = None
        if latest_job is None:
            latest_job = j
            latest_job_dt = cand_dt
        else:
            if (cand_dt is not None and (latest_job_dt is None or cand_dt > latest_job_dt)):
                latest_job = j
                latest_job_dt = cand_dt
            elif cand_dt == latest_job_dt and (j.get("id") or "") > (latest_job.get("id") or ""):
                latest_job = j
                latest_job_dt = cand_dt

    # ---- Respond ----
    result = {
        "service": {
            "id": src.get("id"),
            "key": src.get("key"),
            "display_name": src.get("display_name"),
            "repo_url": src.get("repo_url"),
            "docs_base_url": src.get("docs_base_url"),
            "default_branch": src.get("default_branch"),
            "latest_synced_commit": src.get("latest_synced_commit"),
            "last_synced_at": src.get("last_synced_at"),
            "status": src.get("status"),
            "last_error": src.get("last_error"),
            "created_at": src.get("created_at"),
            "updated_at": src.get("updated_at"),
        },
        "latest_sync_job": None,
    }

    if isinstance(latest_job, dict):
        result["latest_sync_job"] = {
            "id": latest_job.get("id"),
            "status": latest_job.get("status"),
            "force": latest_job.get("force"),
            "requested_source_id": latest_job.get("requested_source_id"),
            "requested_keys": latest_job.get("requested_keys"),
            "started_at": latest_job.get("started_at"),
            "finished_at": latest_job.get("finished_at"),
            "result_summary": latest_job.get("result_summary"),
            "error_message": latest_job.get("error_message"),
            "created_at": latest_job.get("created_at"),
            "updated_at": latest_job.get("updated_at"),
        }

    latency = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
    _log_search("OK", 1, max(0, latency), service_source_ids=[src.get("id")] if src.get("id") else None)

    return {
        "data": result,
        "meta": {
            "resolved_by": "id" if src.get("id") == service else "key",
            "execution_ms": max(0, latency),
        }
    }
